package com.sodi.metareports.client.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="client") public class Client { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=30) private String code; @Column(name="commercial_name",nullable=false) private String commercialName; @Column(name="legal_name") private String legalName; private String description; @Enumerated(EnumType.STRING) private ClientStatus status; @Column(name="primary_currency",length=3) private String primaryCurrency; private String timezone; private boolean active=true; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; @Column(name="updated_at") private Instant updatedAt=Instant.now(); @Version private long version;
 @PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getCommercialName(){return commercialName;} public void setCommercialName(String v){commercialName=v;} public String getLegalName(){return legalName;} public void setLegalName(String v){legalName=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public ClientStatus getStatus(){return status;} public void setStatus(ClientStatus v){status=v;} public String getPrimaryCurrency(){return primaryCurrency;} public void setPrimaryCurrency(String v){primaryCurrency=v;} public String getTimezone(){return timezone;} public void setTimezone(String v){timezone=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;}
}
